pub fn seat(id:&str)->Option<&'static Seat>{SEATS.iter().find(|s|s.id==id)}
pub fn is_seat(id:&str)->bool{seat(id).is_some()}
fn expand(p:&str)->PathBuf{p.strip_prefix("~/").map(|r|dirs::home_dir().unwrap_or_default().join(r)).unwrap_or_else(||PathBuf::from(p))}
fn exts()->&'static [&'static str]{if cfg!(windows){&[".exe",".cmd",".bat"]}else{&[""]}}
fn in_path(exe:&str)->Option<PathBuf>{let sep=if cfg!(windows){';'}else{':'};std::env::var("PATH").ok()?.split(sep).filter(|d|!d.is_empty()).find_map(|d|exts().iter().map(|e|Path::new(d).join(format!("{exe}{e}"))).find(|p|p.is_file()&&(cfg!(windows)||p.metadata().map(|m|m.len()>0).unwrap_or(false))))}
pub fn find(s:&Seat)->Option<(PathBuf,&'static str)>{let ev=std::env::var(format!("AMNI_{}_PATH",s.exe.to_uppercase().replace('-',"_"))).ok().map(PathBuf::from).filter(|p|p.is_file());ev.map(|p|(p,"environment override")).or_else(||in_path(s.exe).map(|p|(p,"PATH"))).or_else(||s.paths.iter().map(|c|expand(c)).find(|p|p.is_file()).map(|p|(p,"known location")))}
pub fn status_json()->serde_json::Value{serde_json::json!({"seats":SEATS.iter().map(|s|{let f=find(s);serde_json::json!({"id":s.id,"label":s.label,"exe":s.exe,"installed":f.is_some(),"path":f.as_ref().map(|x|x.0.display().to_string()).unwrap_or_default(),"found_via":f.as_ref().map(|x|x.1).unwrap_or(""),"hint":s.hint,"get":s.get,"models":s.models})}).collect::<Vec<_>>()})}
fn pins()->&'static Mutex<HashMap<String,String>>{static P:OnceLock<Mutex<HashMap<String,String>>>=OnceLock::new();P.get_or_init(||Mutex::new(HashMap::new()))}
pub fn drop_pin(sid:&str){pins().lock().unwrap().remove(sid);}
pub fn has_pin(sid:&str)->bool{pins().lock().unwrap().contains_key(sid)}
fn mode_of(m:&str,auto:bool)->&'static str{match m{"plan"=>"plan","autonomous"|"auto"=>"auto",_=>if auto{"auto"}else{"edit"}}}
fn model_arg(m:&str)->Option<String>{let t=m.trim();(!t.is_empty()&&t!="default").then(||t.to_string())}
#[derive(Clone,Copy,PartialEq,Debug)]pub enum Feed{Stdin,Argv,File,Jsonl}
pub const EDIT_ALLOW:&[&str]=&["Read","Write","Edit","MultiEdit","Glob","Grep","LS","NotebookEdit","Bash(hcn *)","Bash(*hcn *)","Bash(*hcn)","Bash(hc *)","Bash(* /hc *)","Bash(* /hc)","Bash(gold *)","Bash(*gold *)","Bash(cargo test*)","Bash(cargo build*)","Bash(cargo check*)","Bash(cargo fmt*)","Bash(cargo clippy*)","Bash(*gfxtest.sh *)","Bash(tools/hc/gfxtest.sh *)","Bash(pytest *)","Bash(python -m pytest *)","Bash(python3 -m pytest *)","Bash(go test *)","Bash(npm test *)","Bash(make test *)"];
pub fn argv(s:&Seat,model:&str,mode:&str,auto:bool,cwd:&Path,pin:Option<&str>)->(Vec<String>,Feed){let m=mode_of(mode,auto);let mm=model_arg(model);let mut a:Vec<String>=Vec::new();match s.id{
"claude-code"=>{a.extend(["-p","--output-format","stream-json","--input-format","stream-json","--verbose","--include-partial-messages","--permission-prompts","host","--permission-prompt-tool","stdio","--permission-mode",match m{"plan"=>"plan","auto"=>"bypassPermissions",_=>"acceptEdits"}].map(String::from));if m=="edit"{a.push("--allowed-tools".into());a.extend(EDIT_ALLOW.iter().map(|x|(*x).to_string()));}if let Some(x)=mm{a.extend(["--model".into(),x]);}if let Some(p)=pin{a.extend(["--resume".into(),p.into()]);}(a,Feed::Jsonl)}
"codex"=>{a.extend(["exec","--skip-git-repo-check"].map(String::from));a.extend(match m{"plan"=>vec!["--sandbox".to_string(),"read-only".into()],"auto"=>vec!["--full-auto".to_string()],_=>vec!["--sandbox".to_string(),"workspace-write".into()]});if let Some(x)=mm{a.extend(["-m".into(),x]);}a.push("-".into());(a,Feed::Stdin)}
"grok-cli"=>{a.extend(["--prompt-file","{file}","--output-format","streaming-messages-json","--include-partial-messages","--no-memory","--no-subagents","--max-turns","12","--permission-mode",if m=="plan"{"plan"}else{"dontAsk"}].map(String::from));if let Some(x)=mm{a.extend(["--model".into(),x]);}(a,Feed::File)}
"antigravity"=>{a.extend(["-p","{prompt}","--output-format","json","--add-dir",&cwd.display().to_string(),"--dangerously-skip-permissions","--mode",if m=="plan"{"plan"}else{"accept-edits"}].map(String::from));if let Some(p)=pin{a.extend(["--conversation".into(),p.into()]);}if let Some(x)=mm{a.extend(["--model".into(),x]);}(a,Feed::Argv)}
"copilot"=>{a.extend(["-p","{prompt}"].map(String::from));if m!="plan"{a.push("--allow-all-tools".into());}if let Some(x)=mm{a.extend(["--model".into(),x]);}(a,Feed::Argv)}
"cursor"=>{a.extend(["-p","{prompt}","--trust","--output-format","text"].map(String::from));if let Some(x)=mm{a.extend(["--model".into(),x]);}(a,Feed::Argv)}
_=>{a.extend(["run","--auto","--format","json"].map(String::from));if let Some(x)=mm{a.extend(["-m".into(),x]);}a.push("-".into());(a,Feed::Stdin)}}}
pub fn transcript_prefix(messages:&[serde_json::Value],user_msg:&str)->String{let turns:Vec<String>=messages.iter().filter(|m|matches!(m["role"].as_str(),Some("user")|Some("assistant"))).filter_map(|m|m["content"].as_str().map(|c|(m["role"].as_str().unwrap_or("").to_string(),c.to_string()))).filter(|(_,c)|c!=user_msg).map(|(r,c)|format!("{}: {}",if r=="user"{"User"}else{"Assistant"},if c.chars().count()>1500{c.chars().take(1500).collect::<String>()+" …"}else{c})).collect();let tail:Vec<&String>=turns.iter().rev().take(8).collect::<Vec<_>>().into_iter().rev().collect();if tail.is_empty(){user_msg.to_string()}else{format!("Earlier in this conversation:\n{}\n\nNow the user says:\n{}",tail.iter().map(|s|s.as_str()).collect::<Vec<_>>().join("\n\n"),user_msg)}}
fn json_text(line:&str,sid_out:&mut Option<String>)->Option<String>{let d:serde_json::Value=serde_json::from_str(line.trim()).ok()?;if let Some(s)=d.get("session_id").and_then(|v|v.as_str()){if !s.is_empty(){*sid_out=Some(s.to_string());}}if let Some(s)=d.get("conversation_id").or(d.get("conversationId")).and_then(|v|v.as_str()){*sid_out=Some(s.to_string());}let t=d.get("type").and_then(|v|v.as_str()).unwrap_or("");if t=="result"{return d.get("result").and_then(|v|v.as_str()).map(|s|format!("\u{E000}{s}"));}if t=="stream_event"{let ev=&d["event"];if ev["type"]=="content_block_delta"&&ev["delta"]["type"]=="text_delta"{return ev["delta"]["text"].as_str().map(String::from);}return None;}if t=="assistant"{return None;}for k in ["text","content","response","output"]{if let Some(s)=d.get(k).and_then(|v|v.as_str()){return Some(s.to_string());}}if let Some(p)=d.get("part"){if p["type"]=="text"{return p["text"].as_str().map(String::from);}}None}
pub fn finalize(seat:&Seat,stdout:&str)->(String,Option<String>){let mut sid=None;let jsonish=matches!(seat.id,"claude-code"|"grok-cli"|"antigravity"|"opencode");if !jsonish{let mut t=stdout.trim().to_string();if seat.id=="codex"{if let Some(i)=t.rfind("\ncodex\n"){t=t[i+7..].trim().to_string();}}return (t,None);}let mut deltas=String::new();let mut finals:Vec<String>=Vec::new();for l in stdout.lines(){if let Some(t)=json_text(l,&mut sid){if let Some(r)=t.strip_prefix('\u{E000}'){finals.push(r.to_string());}else{deltas.push_str(&t);}}}let out=finals.last().cloned().filter(|s|!s.trim().is_empty()).unwrap_or(deltas);(if out.trim().is_empty(){stdout.trim().to_string()}else{out.trim().to_string()},sid)}
pub fn user_line(prompt:&str)->String{serde_json::json!({"type":"user","message":{"role":"user","content":[{"type":"text","text":prompt}]}}).to_string()}
pub fn control_reply(request_id:&str,allow:bool,input:&serde_json::Value)->String{let resp=if allow{serde_json::json!({"behavior":"allow","updatedInput":input})}else{serde_json::json!({"behavior":"deny","message":"User denied this tool"})};serde_json::json!({"type":"control_response","response":{"subtype":"success","request_id":request_id,"response":resp}}).to_string()}
fn input_ready(input:&serde_json::Value)->bool{match input{serde_json::Value::Null=>false,serde_json::Value::Object(m)=>!m.is_empty(),serde_json::Value::Array(a)=>!a.is_empty(),serde_json::Value::String(s)=>!s.is_empty(),_=>true}}
fn arg_summary(tool:&str,input:&serde_json::Value)->String{let s=if let Some(c)=input.get("command").and_then(|v|v.as_str()){c.to_string()}else if let Some(p)=input.get("file_path").or(input.get("path")).and_then(|v|v.as_str()){p.to_string()}else if let Some(q)=input.get("query").or(input.get("pattern")).and_then(|v|v.as_str()){q.to_string()}else{input.to_string()};let s=s.replace('\n'," ");format!("{} · {}",tool,if s.chars().count()>120{s.chars().take(120).collect::<String>()+" …"}else{s})}
#[derive(Debug)]
pub enum StreamEv{Text(String),ToolStart{name:String,input:serde_json::Value},ToolEnd{name:String,input:serde_json::Value,output:String,status:String},Permit{request_id:String,tool:String,input:serde_json::Value},Done(String),Ignore}
fn take_sid(d:&serde_json::Value,sid_out:&mut Option<String>){if let Some(s)=d.get("session_id").and_then(|v|v.as_str()){if !s.is_empty(){*sid_out=Some(s.to_string());}}if let Some(s)=d.get("conversation_id").or(d.get("conversationId")).and_then(|v|v.as_str()){*sid_out=Some(s.to_string());}}
fn content_parts(d:&serde_json::Value)->Vec<&serde_json::Value>{d.get("message").and_then(|m|m.get("content")).or(d.get("content")).and_then(|c|c.as_array()).map(|a|a.iter().collect()).unwrap_or_default()}
pub fn stream_ev(line:&str,sid_out:&mut Option<String>)->StreamEv{let Ok(d)=serde_json::from_str::<serde_json::Value>(line.trim()) else {return StreamEv::Ignore;};take_sid(&d,sid_out);let t=d.get("type").and_then(|v|v.as_str()).unwrap_or("");if t=="control_request"{let req=&d["request"];if req["subtype"]=="can_use_tool"{let tool=req.get("tool_name").and_then(|v|v.as_str()).unwrap_or("tool").to_string();let input=req.get("input").cloned().unwrap_or(serde_json::json!({}));let id=d.get("request_id").and_then(|v|v.as_str()).unwrap_or("").to_string();if !id.is_empty(){return StreamEv::Permit{request_id:id,tool,input};}}return StreamEv::Ignore;}if t=="assistant"{for p in content_parts(&d){if p.get("type").and_then(|v|v.as_str())==Some("tool_use"){let name=p.get("name").and_then(|v|v.as_str()).unwrap_or("tool").to_string();let input=p.get("input").cloned().unwrap_or(serde_json::json!({}));if input_ready(&input){return StreamEv::ToolStart{name,input};}}}return StreamEv::Ignore;}if t=="user"{for p in content_parts(&d){if p.get("type").and_then(|v|v.as_str())==Some("tool_result")||p.get("tool_use_id").is_some(){let output=p.get("content").and_then(|v|v.as_str()).unwrap_or("").to_string();let err=p.get("is_error").and_then(|v|v.as_bool()).unwrap_or(false);return StreamEv::ToolEnd{name:"tool".into(),input:serde_json::json!({}),output,status:if err{"error"}else{"ok"}.into()};}}return StreamEv::Ignore;}if t=="stream_event"{let ev=&d["event"];let et=ev.get("type").and_then(|v|v.as_str()).unwrap_or("");if et=="content_block_start"{let b=&ev["content_block"];if b["type"]=="tool_use"{let name=b.get("name").and_then(|v|v.as_str()).unwrap_or("tool").to_string();let input=b.get("input").cloned().unwrap_or(serde_json::json!({}));if input_ready(&input){return StreamEv::ToolStart{name,input};}}}if et=="content_block_delta"&&ev["delta"]["type"]=="text_delta"{if let Some(s)=ev["delta"]["text"].as_str(){return StreamEv::Text(s.to_string());}}return StreamEv::Ignore;}if t=="result"{return StreamEv::Done(d.get("result").and_then(|v|v.as_str()).unwrap_or("").to_string());}StreamEv::Ignore}
struct Live{stdin:Mutex<Option<tokio::process::ChildStdin>>,pending:Mutex<HashMap<String,serde_json::Value>>}
fn lives()->&'static Mutex<HashMap<String,Arc<Live>>>{static L:OnceLock<Mutex<HashMap<String,Arc<Live>>>>=OnceLock::new();L.get_or_init(||Mutex::new(HashMap::new()))}
pub async fn answer(amni_sid:&str,request_id:&str,allow:bool)->Result<(),String>{let live={let g=lives().lock().unwrap();g.get(amni_sid).cloned()};let Some(live)=live else{return Err("no running turn to approve".into());};let input={let mut p=live.pending.lock().unwrap();p.remove(request_id).ok_or_else(||"unknown or already answered request".to_string())?};let line=control_reply(request_id,allow,&input);let mut si={let mut g=live.stdin.lock().unwrap();g.take().ok_or_else(||"the turn has already finished".to_string())?};use tokio::io::AsyncWriteExt;let w=async{si.write_all(line.as_bytes()).await?;si.write_all(b"\n").await?;si.flush().await?;Ok::<_,std::io::Error>(())}.await;live.stdin.lock().unwrap().replace(si);w.map_err(|e|e.to_string())}
async fn emit(tx:&tokio::sync::mpsc::Sender<axum::response::sse::Event>,name:&str,data:serde_json::Value){let _=tx.send(axum::response::sse::Event::default().event(name).data(data.to_string())).await;}
pub async fn run(seat:&'static Seat,model:&str,mode:&str,auto:bool,cwd:&Path,prompt:&str,amni_sid:&str,interrupt:Arc<AtomicBool>,tx:tokio::sync::mpsc::Sender<axum::response::sse::Event>)->Result<String,String>{let fallback=std::env::current_dir().unwrap_or_else(|_|PathBuf::from("."));let cwd:&Path=if cwd.is_dir(){cwd}else{&fallback};let (path,_how)=find(seat).ok_or_else(||format!("{} is not installed. Get it: {} . {}",seat.label,seat.get,seat.hint))?;let pin=pins().lock().unwrap().get(amni_sid).cloned();let (mut a,feed)=argv(seat,model,mode,auto,cwd,pin.as_deref());let mut tmp:Option<PathBuf>=None;let long=prompt.len()>2400;if feed==Feed::File||(feed==Feed::Argv&&long){let p=std::env::temp_dir().join(format!("amni_{}_{}.txt",seat.exe,uuid::Uuid::new_v4()));tokio::fs::write(&p,prompt).await.map_err(|e|e.to_string())?;let ptr=format!("Read the UTF-8 task file at this absolute path and complete it fully; reply with only your answer text: {}",p.display());for x in a.iter_mut(){if x=="{file}"{*x=p.display().to_string();}if x=="{prompt}"{*x=ptr.clone();}}tmp=Some(p);}else{for x in a.iter_mut(){if x=="{prompt}"{*x=prompt.to_string();}}}
let ps=path.display().to_string();let wrap=cfg!(windows)&&ps.to_lowercase().ends_with(".cmd")||ps.to_lowercase().ends_with(".bat");let mut cmd=if wrap{let mut c=tokio::process::Command::new("cmd");c.arg("/c").arg(&ps);c}else{tokio::process::Command::new(&ps)};cmd.args(&a).current_dir(cwd).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).env("AMNI_CODE","1").env("CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC","1").env("DISABLE_TELEMETRY","1").env("DO_NOT_TRACK","1");
#[cfg(windows)]{cmd.creation_flags(0x08000000);}
let _=emit(&tx,"thinking",serde_json::json!({"text":format!("{} · {} in {}",seat.label,if pin.is_some(){"resuming session"}else{"starting"},cwd.display())})).await;
let mut child=cmd.spawn().map_err(|e|format!("could not start {} ({} in {}): {e}",seat.label,ps,cwd.display()))?;
let mut stdin=child.stdin.take();
if feed==Feed::Jsonl{if let Some(ref mut si)=stdin{use tokio::io::AsyncWriteExt;let line=user_line(prompt);si.write_all(line.as_bytes()).await.map_err(|e|e.to_string())?;si.write_all(b"\n").await.map_err(|e|e.to_string())?;si.flush().await.map_err(|e|e.to_string())?;}}else if feed==Feed::Stdin{if let Some(si)=stdin.take(){let body=prompt.to_string();tokio::spawn(async move{use tokio::io::AsyncWriteExt;let mut si=si;let _=si.write_all(body.as_bytes()).await;let _=si.shutdown().await;});}}else{let _=stdin.take();}
let live=Arc::new(Live{stdin:Mutex::new(stdin),pending:Mutex::new(HashMap::new())});lives().lock().unwrap().insert(amni_sid.to_string(),live.clone());
let stdout=child.stdout.take().ok_or("no stdout")?;let stderr=child.stderr.take();let txc=tx.clone();let sid_label=seat.label.to_string();let live_r=live.clone();let reader=tokio::spawn(async move{let mut out=String::new();let mut lines=BufReader::new(stdout).lines();let mut sid=None;let mut acc=String::new();let mut last_tool=String::new();while let Ok(Some(l))=lines.next_line().await{out.push_str(&l);out.push('\n');match stream_ev(&l,&mut sid){StreamEv::Text(s)=>{acc.push_str(&s);let shown=acc.chars().rev().take(160).collect::<String>().chars().rev().collect::<String>();let _=emit(&txc,"thinking",serde_json::json!({"text":format!("{} · {}",sid_label,shown)})).await;}StreamEv::ToolStart{name,input}=>{if input_ready(&input){last_tool=name.clone();let _=emit(&txc,"tool_start",serde_json::json!({"tool":&name,"input":&input,"summary":arg_summary(&name,&input)})).await;}}StreamEv::ToolEnd{name,input,output,status}=>{let name=if name=="tool"&&!last_tool.is_empty(){last_tool.clone()}else{name};let _=emit(&txc,"tool_result",serde_json::json!({"tool":&name,"input":&input,"output":output.chars().take(4000).collect::<String>(),"status":status})).await;}StreamEv::Permit{request_id,tool,input}=>{live_r.pending.lock().unwrap().insert(request_id.clone(),input.clone());let _=emit(&txc,"approval",serde_json::json!({"request_id":request_id,"tool":&tool,"summary":arg_summary(&tool,&input),"input":&input})).await;}StreamEv::Done(s)=>{if !s.is_empty(){acc=s.clone();let _=emit(&txc,"thinking",serde_json::json!({"text":format!("{} · {}",sid_label,s.chars().take(160).collect::<String>())})).await;}let _=live_r.stdin.lock().unwrap().take();}StreamEv::Ignore=>{}} }out});
let err_task=tokio::spawn(async move{let mut e=String::new();if let Some(se)=stderr{let mut lines=BufReader::new(se).lines();while let Ok(Some(l))=lines.next_line().await{e.push_str(&l);e.push('\n');}}e});
let status=loop{tokio::select!{s=child.wait()=>break s.map_err(|e|e.to_string())?,_=tokio::time::sleep(std::time::Duration::from_millis(250))=>{if interrupt.load(Ordering::Relaxed){let _=child.kill().await;if let Some(p)=tmp.take(){let _=tokio::fs::remove_file(p).await;}lives().lock().unwrap().remove(amni_sid);return Err("interrupted".into());}}}};
let out=reader.await.unwrap_or_default();let err=err_task.await.unwrap_or_default();if let Some(p)=tmp.take(){let _=tokio::fs::remove_file(p).await;}lives().lock().unwrap().remove(amni_sid);
let (text,sid)=finalize(seat,&out);if let Some(s)=sid{pins().lock().unwrap().insert(amni_sid.to_string(),s);}
if text.is_empty(){let e=err.trim();return Err(if !status.success(){format!("{} exited with {} · {}",seat.label,status.code().unwrap_or(-1),e.chars().take(600).collect::<String>())}else{format!("{} produced no text · {}",seat.label,e.chars().take(600).collect::<String>())});}
Ok(text)}
#[cfg(test)]mod tests{use super::*;use std::path::Path;
#[test]fn plan_mode_maps_to_read_only_flags(){let c=Path::new(".");let (a,f)=argv(seat("claude-code").unwrap(),"default","plan",false,c,None);assert!(a.windows(2).any(|w|w==["--permission-mode","plan"])&&f==Feed::Jsonl&&!a.iter().any(|x|x=="--model"));let (a,_)=argv(seat("codex").unwrap(),"gpt-5","plan",true,c,None);assert!(a.windows(2).any(|w|w==["--sandbox","read-only"])&&a.windows(2).any(|w|w==["-m","gpt-5"])&&a.last().unwrap()=="-");let (a,_)=argv(seat("codex").unwrap(),"default","edit",true,c,None);assert!(a.iter().any(|x|x=="--full-auto"));for s in SEATS{let (a,_)=argv(s,"default","auto",true,c,None);assert!(!a.iter().any(|x|x=="--yolo"||x=="-f"||x=="--dangerously-bypass-approvals-and-sandbox"),"{}",s.id);}}
#[test]fn claude_pin_becomes_resume(){let (a,_)=argv(seat("claude-code").unwrap(),"opus","edit",false,Path::new("."),Some("abc"));assert!(a.windows(2).any(|w|w==["--resume","abc"])&&a.windows(2).any(|w|w==["--model","opus"])&&a.windows(2).any(|w|w==["--permission-mode","acceptEdits"]));}
#[test]fn edit_mode_allows_project_build_tools_and_hosts_prompts(){let (a,f)=argv(seat("claude-code").unwrap(),"default","edit",false,Path::new("."),None);assert_eq!(f,Feed::Jsonl);assert!(a.windows(2).any(|w|w==["--input-format","stream-json"]));assert!(a.windows(2).any(|w|w==["--permission-prompts","host"]));assert!(a.windows(2).any(|w|w==["--permission-prompt-tool","stdio"]));assert!(a.iter().any(|x|*x=="--allowed-tools"));assert!(EDIT_ALLOW.iter().all(|t|a.iter().any(|x|x==t)));let (b,_)=argv(seat("claude-code").unwrap(),"default","auto",false,Path::new("."),None);assert!(b.windows(2).any(|w|w==["--permission-mode","bypassPermissions"]));assert!(!b.iter().any(|x|*x=="--allowed-tools"));}
#[test]fn stream_json_final_wins_and_pins_session(){let s=seat("claude-code").unwrap();let out="{\"type\":\"system\",\"session_id\":\"s-1\"}\n{\"type\":\"stream_event\",\"event\":{\"type\":\"content_block_delta\",\"delta\":{\"type\":\"text_delta\",\"text\":\"par\"}}}\n{\"type\":\"stream_event\",\"event\":{\"type\":\"content_block_delta\",\"delta\":{\"type\":\"text_delta\",\"text\":\"tial\"}}}\n{\"type\":\"result\",\"result\":\"# Done\\n\\nAll good.\"}\n";let (t,sid)=finalize(s,out);assert_eq!(t,"# Done\n\nAll good.");assert_eq!(sid.as_deref(),Some("s-1"));let (t2,_)=finalize(s,"{\"type\":\"stream_event\",\"event\":{\"type\":\"content_block_delta\",\"delta\":{\"type\":\"text_delta\",\"text\":\"only deltas\"}}}\n");assert_eq!(t2,"only deltas");}
#[test]fn parses_tools_and_permission_requests(){let mut sid=None;match stream_ev("{\"type\":\"stream_event\",\"event\":{\"type\":\"content_block_start\",\"content_block\":{\"type\":\"tool_use\",\"name\":\"Bash\",\"input\":{}}}}",&mut sid){StreamEv::Ignore=>(),x=>{panic!("empty start {x:?}")}}match stream_ev("{\"type\":\"assistant\",\"message\":{\"content\":[{\"type\":\"tool_use\",\"name\":\"Bash\",\"input\":{\"command\":\"echo hi\"}}]}}",&mut sid){StreamEv::ToolStart{name,input}=>assert!(name=="Bash"&&input["command"]=="echo hi"),x=>{panic!("{x:?}")}}match stream_ev("{\"type\":\"control_request\",\"request_id\":\"req_7\",\"request\":{\"subtype\":\"can_use_tool\",\"tool_name\":\"Bash\",\"input\":{\"command\":\"uname\"}}}",&mut sid){StreamEv::Permit{request_id,tool,input}=>assert!(request_id=="req_7"&&tool=="Bash"&&input["command"]=="uname"),x=>{panic!("{x:?}")}}let allow=control_reply("req_7",true,&serde_json::json!({"command":"uname"}));let v:serde_json::Value=serde_json::from_str(&allow).unwrap();assert_eq!(v["type"],"control_response");assert_eq!(v["response"]["request_id"],"req_7");assert_eq!(v["response"]["response"]["behavior"],"allow");let deny=control_reply("req_7",false,&serde_json::json!({}));let d:serde_json::Value=serde_json::from_str(&deny).unwrap();assert_eq!(d["response"]["response"]["behavior"],"deny");assert!(user_line("hi").contains("\"type\":\"user\""));}
#[test]fn codex_keeps_only_the_answer_after_its_chrome(){let (t,_)=finalize(seat("codex").unwrap(),"OpenAI Codex v1\n--------\nuser\nhello\ncodex\nThe **answer** is 4.\n");assert_eq!(t,"The **answer** is 4.");}
#[test]fn transcript_prefix_is_bounded_and_skips_current_turn(){let msgs:Vec<serde_json::Value>=(0..20).map(|i|serde_json::json!({"role":if i%2==0{"user"}else{"assistant"},"content":format!("turn {i} {}","x".repeat(2000))})).collect();let p=transcript_prefix(&msgs,"now");assert!(p.starts_with("Earlier in this conversation:")&&p.ends_with("\nnow")&&p.matches("turn ").count()==8&&p.contains(" …")&&!p.contains("turn 0 "));assert_eq!(transcript_prefix(&[],"solo"),"solo");}
#[test]fn find_rejects_bad_env_override(){std::env::set_var("AMNI_CLAUDE_PATH","C:/definitely/not/here.exe");let f=find(seat("claude-code").unwrap());assert!(f.map(|x|x.1!="environment override").unwrap_or(true));std::env::remove_var("AMNI_CLAUDE_PATH");}}
